import math
assert count_plane_waves(10.0, 0.1) == 1, "only G = 0 fits below the first shell"
assert count_plane_waves(10.0, 0.2) == 7, "G = 0 plus the six vectors (+-1, 0, 0), ..."

def _brute(a, ecut):
    n = int(math.sqrt(2 * ecut) * a / (2 * math.pi)) + 2
    c = 0
    for i in range(-n, n + 1):
        for j in range(-n, n + 1):
            for k in range(-n, n + 1):
                if 0.5 * (2 * math.pi / a) ** 2 * (i * i + j * j + k * k) <= ecut:
                    c += 1
    return c

for a, e in [(10.26, 7.0), (6.0, 15.0), (12.0, 3.3)]:
    assert count_plane_waves(a, e) == _brute(a, e), (a, e)
